"""@username against the running live stack (S-03, the owner's decision of 25 Oct — Facebook's rule: names may be alike, every member
has a unique username; 0070_usernames, tools/names/username_rule.mjs, web/src/username.js).
  1. concurrent sign-ups with the SAME name (the sign-up API, in parallel threads): every member gets a different username — base,
     base.2 … base.N exactly —, all keys different (the advisory lock and the unique index, retried);
  2. made from real names (Arabic, Latin, Greek, Cyrillic, titles, brackets) through the sign-up API: the database's username is the
     base the SERVED app's code makes of the name (usBase in the adapter the live app serves), numbered when taken;
  3. written ONLY through set_username(): a member's PATCH of username / username_key is refused (42501), other columns still save;
     set_username: capitals and a leading @ written small / dropped, the reasons (format, reserved, taken — a look-alike of a taken one
     too —, held 30 days for the member who gave it up, who can take it back), username_available says the same; anon can call neither;
  4. the app: the profile says @username under the name (left to right), Edit Profile has the Username field — a taken one is said to be
     taken, a free one available —, saving writes it through set_username and the profile shows it; no JavaScript errors.
  python3 tests/e2e/username_test.py        (tools/local-supabase/start.sh; settings in tests/e2e/_dx.py)"""
import json, os, re, threading, urllib.request, urllib.error
from playwright.sync_api import sync_playwright
from _dx import APP_URL as U, R, T, sql, ST, NT, wait_for, done   # shared settings: tests/e2e/_dx.py

PW = 'Strong-pass-2026'
BASE = U.rstrip('/')
def q(s): return "'" + s.replace("'", "''") + "'"

def http(method, path, body=None, key='', token=''):
    req = urllib.request.Request(BASE + path, data=None if body is None else json.dumps(body).encode(), method=method,
                                 headers={'apikey': key, 'authorization': 'Bearer ' + (token or key), 'content-type': 'application/json', 'prefer': 'return=representation'})
    try:
        with urllib.request.urlopen(req, timeout=30) as r: t = r.read().decode(); return r.status, (json.loads(t) if t else None)
    except urllib.error.HTTPError as e:
        t = e.read().decode()
        try: return e.code, json.loads(t)
        except Exception: return e.code, t

with sync_playwright() as p:
    b = p.chromium.launch(args=['--no-sandbox']); ctx = b.new_context(viewport={'width': 1440, 'height': 900}); pg = ctx.new_page(); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)[:150]))
    pg.goto(U, wait_until='load'); pg.wait_for_timeout(500); pg.evaluate('endSplash()'); pg.wait_for_timeout(900)
    KEY = pg.evaluate('dxLive.sb.supabaseKey')
    T('the served app carries the anon key and the username rule (web/src/username.js)', bool(KEY) and pg.evaluate("typeof window.dxUsername.key") == 'function')
    # the served adapter's usBase (the generated code, run in a blank page: the app's CSP forbids eval)
    src = pg.evaluate("() => [...document.scripts].map((s) => s.src).find((s) => /\\/adapter\\.[0-9a-f]+\\.js/.test(s))")
    t = urllib.request.urlopen(src).read().decode()
    nm_a, nm_b = t.index('/* >>> generated by tools/names/name_rule.mjs'), t.index('/* <<< generated */')
    us_a, us_b = t.index('/* >>> generated by tools/names/username_rule.mjs'), t.index('/* <<< generated username */')
    # the layer (web/src/username.js) as the app page has it — an inline script of the build, or the repository's file
    lay = pg.evaluate("(() => { const s = document.querySelector('script[data-dx=username]'); return s ? s.textContent : ''; })()") or open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../web/src/username.js'), encoding='utf8').read()
    rule = ctx.new_page(); rule.set_content('<p>rule</p>')
    rule.evaluate("([l, n, u]) => { new Function(l)(); window.__US = new Function(n + '\\n' + u + '\\nreturn { usBase };')(); }",
                  [lay, t[t.index('\n', nm_a) + 1:nm_b], t[t.index('\n', us_a) + 1:us_b]])
    def app_base(name): return rule.evaluate('(n) => window.__US.usBase(n)', name)

    # ── 1. concurrent sign-ups with the same name ──
    same = f'Dr. Same Name {NT}'; N = 16; out = [None] * N
    def go(i): out[i] = http('POST', '/auth/v1/signup', {'email': f'un-c{i}-{ST}@un.test', 'password': PW, 'data': {'name': same}}, KEY)
    th = [threading.Thread(target=go, args=(i,)) for i in range(N)]; [x.start() for x in th]; [x.join() for x in th]
    T(f'concurrent sign-ups: all {N} answered 200 with a session', all(o and o[0] == 200 and isinstance(o[1], dict) and o[1].get('access_token') for o in out), [o[0] for o in out if o])
    rows = sql(f"select p.username || '|' || p.username_key from public.profiles p join auth.users u on u.id = p.id where u.email like 'un-c%-{ST}@un.test' order by p.username").split('\n')
    names = sorted(r.split('|')[0] for r in rows if r); keys = {r.split('|')[1] for r in rows if r}
    base = sql(f"select public.username_base({q(same)})")
    want = sorted([base] + [f'{base}.{i}' for i in range(2, N + 1)])
    T(f'concurrent sign-ups: {N} members with one name got {base}, {base}.2 … {base}.{N} — each once, all keys different', names == want and len(keys) == N, names)

    # ── 2. made from real names: the database = the served app ──
    real = ['محمد أحمد', 'عبد الرحمن عبد العزيز', 'José Ali', 'Dr. Haytham Dweedar', 'د. هالة الشامي', 'أبو بكر الصديق', 'Мария Иванова', 'Νίκος Παπαδόπουλος',
            'Ahmed Ali (MBA)', 'Mo’men Abd El-Raouf', 'بىىىام علي', 'Om Kalthoum Ibrahim', 'Søren Łukasz', 'Strauß', 'Drugbox Finance', 'Dr. Maha Moderator', 'مي', 'Ali']
    for i, nm in enumerate(real):
        name = f'{nm} {NT}' if not re.search('[؀-ۿ]', nm) else f'{nm} {NT}'
        st, body = http('POST', '/auth/v1/signup', {'email': f'un-r{i}-{ST}@un.test', 'password': PW, 'data': {'name': name}}, KEY)
        got = sql(f"select p.username from public.profiles p join auth.users u on u.id = p.id where u.email = 'un-r{i}-{ST}@un.test'")
        ab = app_base(sql(f"select p.name from public.profiles p join auth.users u on u.id = p.id where u.email = 'un-r{i}-{ST}@un.test'"))
        T(f'real name «{nm}»: the username is the served app\'s base for the stored name ({ab}), numbered only when taken', st == 200 and bool(got) and (got == ab or re.fullmatch(re.escape(ab) + r'\.\d+', got) is not None), [st, got, ab])

    # ── 3. written only through set_username() ──
    st, s1 = http('POST', '/auth/v1/signup', {'email': f'un-a-{ST}@un.test', 'password': PW, 'data': {'name': f'Dr. Rpc Owner {NT}'}}, KEY)
    st2, s2 = http('POST', '/auth/v1/signup', {'email': f'un-b-{ST}@un.test', 'password': PW, 'data': {'name': f'Dr. Rpc Other {NT}'}}, KEY)
    A, B = s1['user']['id'], s2['user']['id']; ta, tb = s1['access_token'], s2['access_token']
    ua = sql(f"select username from public.profiles where id = '{A}'"); ub = sql(f"select username from public.profiles where id = '{B}'")
    st, r = http('PATCH', f'/rest/v1/profiles?id=eq.{A}', {'username': 'my.own.pick.' + ST[:6]}, KEY, ta)
    T('a member\'s PATCH of username is refused (42501), the username stays', st in (401, 403) and isinstance(r, dict) and r.get('code') == '42501' and sql(f"select username from public.profiles where id = '{A}'") == ua, [st, r])
    st, r = http('PATCH', f'/rest/v1/profiles?id=eq.{A}', {'username_key': 'forged'}, KEY, ta)
    T('a member\'s PATCH of username_key is refused (42501)', st in (401, 403) and isinstance(r, dict) and r.get('code') == '42501', [st, r])
    st, r = http('PATCH', f'/rest/v1/profiles?id=eq.{A}&select=id,headline', {'headline': 'Pharmacist ' + NT}, KEY, ta)
    T('…other columns still save (headline)', st == 200 and r and r[0]['headline'] == 'Pharmacist ' + NT, [st, r])
    new = 'rpc.owner.' + ST[-6:]
    st, r = http('POST', '/rest/v1/rpc/set_username', {'p_username': '@' + new.upper()}, KEY, ta)
    T('set_username: capitals and a leading @ → written small, stored with its key', st == 200 and r == new and sql(f"select username || '|' || (username_key = public.username_key(username)) from public.profiles where id = '{A}'") == new + '|true', [st, r])
    T('…the old username is held for its member for 30 days', sql(f"select count(*) from public.username_holds where profile_id = '{A}' and username = {q(ua)} and held_until > now() + interval '29 days'") == '1')
    for typed, code, pat in (('ahmed_ali', 23514, 'remove'), ('ali', 23514, 'at least 5'), ('drugbox.support', 23514, 'kept for Drugbox'), (new.replace('o', '0', 1), None, 'is taken')):
        st, r = http('POST', '/rest/v1/rpc/set_username', {'p_username': typed}, KEY, tb)
        T(f'set_username «{typed}»: refused, the reason in words', st >= 400 and isinstance(r, dict) and re.search(pat, r.get('message', '')) is not None and str(r.get('hint', '')).startswith('username:'), [st, r])
    st, r = http('POST', '/rest/v1/rpc/set_username', {'p_username': ua}, KEY, tb)
    T('set_username: the username another member just gave up is held (30 days) — refused', st >= 400 and isinstance(r, dict) and 'kept for them for 30 days' in r.get('message', ''), [st, r])
    st, r = http('POST', '/rest/v1/rpc/username_available', {'p_username': ua}, KEY, tb)
    T('username_available: held / taken (a look-alike) / reserved / free', st == 200 and r['reason'] == 'held'
      and http('POST', '/rest/v1/rpc/username_available', {'p_username': new.replace('l', '1', 1)}, KEY, tb)[1]['reason'] == 'taken'
      and http('POST', '/rest/v1/rpc/username_available', {'p_username': 'admin2'}, KEY, tb)[1]['reason'] == 'reserved'
      and http('POST', '/rest/v1/rpc/username_available', {'p_username': 'free.name.' + ST[-6:]}, KEY, tb)[1]['ok'] is True, r)
    st, r = http('POST', '/rest/v1/rpc/set_username', {'p_username': ua}, KEY, ta)
    T('set_username: the member who gave it up takes it back', st == 200 and r == ua and sql(f"select count(*) from public.username_holds where username_key = public.username_key({q(ua)})") == '0', [st, r])
    for fn in ('set_username', 'username_available'):
        st, r = http('POST', f'/rest/v1/rpc/{fn}', {'p_username': 'anon.name.x'}, KEY)
        T(f'anon cannot call {fn}', st in (401, 403, 404) and sql(f"select count(*) from public.profiles where username = 'anon.name.x'") == '0', [st, r])
    st, r = http('GET', f'/rest/v1/profiles?select=id,name,username&id=eq.{A}', None, KEY, tb)
    T('another member reads the username by column', st == 200 and r and r[0]['username'] == ua, [st, r])

    # ── 4. the app ──
    pg.fill('#loginEmail', f'un-a-{ST}@un.test'); pg.fill('#loginPw', PW); pg.click('#loginPage button.f-btn')
    wait_for(lambda: pg.is_visible('#app'), 15); pg.wait_for_timeout(1200)
    pg.evaluate('gotoProfile(ME.id)'); pg.wait_for_timeout(1500)
    un = pg.evaluate("(() => { const e = document.querySelector('#content .profile-username'); return e ? [e.innerText.trim(), getComputedStyle(e.querySelector('bdi')).direction] : null; })()")
    T('my profile says @username under my name, left to right', un == ['@' + ua, 'ltr'], un)
    pg.evaluate('showEditProfile()'); pg.wait_for_timeout(400)
    T('Edit Profile has the Username field with my @username', pg.input_value('#ep-user') == '@' + ua, pg.input_value('#ep-user'))
    pg.fill('#ep-user', ub); pg.wait_for_timeout(1500)
    T('Edit Profile: another member\'s username is said to be taken (asked of the database)', 'is taken' in pg.inner_text('#ep-user-st'), pg.inner_text('#ep-user-st'))
    mine = 'my.choice.' + ST[-6:]
    pg.fill('#ep-user', mine); pg.wait_for_timeout(1500)
    T('Edit Profile: a free one is said to be available', 'is available' in pg.inner_text('#ep-user-st'), pg.inner_text('#ep-user-st'))
    pg.click('.modal-bg [onclick^="saveProfile"]'); pg.wait_for_timeout(2000)
    T('Save Changes writes it through set_username and the profile shows it', sql(f"select username from public.profiles where id = '{A}'") == mine
      and ('@' + mine) in pg.inner_text('#content .profile-username') and sql(f"select count(*) from public.username_changes where profile_id = '{A}' and new_username = '{mine}'") == '1')
    pg.evaluate('showEditProfile()'); pg.wait_for_timeout(400); pg.fill('#ep-user', ub); pg.click('.modal-bg [onclick^="saveProfile"]'); pg.wait_for_timeout(1500)
    T('Save Changes with a taken username: refused next to the field, nothing changed', 'is taken' in pg.inner_text('#ep-err') and sql(f"select username from public.profiles where id = '{A}'") == mine, pg.inner_text('#ep-err'))
    T('no JavaScript errors', not errs, errs)
    b.close()
done()
